(function(E){ const x = E["exam-07"] = E["exam-07"] || {units:{}}; (x.units = x.units || {})["x07-r1"] = {"id":"x07-r1","patterns":["RA-history","GT1-ads","PARA-cause"],"title":{"en":"Reading 1: Passage 1 / Section 1","tr":"Reading 1: Passage 1 / Section 1","fa":"Reading ۱: متن ۱ (Passage 1) / بخش ۱ (Section 1)"},"objective":{"en":"In this lesson you will learn to complete notes on a history with one word from the passage, and to decide TRUE, FALSE or NOT GIVEN by checking words about time and order.","tr":"Bu derste bir tarih metni üzerine notları metinden tek kelimeyle tamamlamayı ve zaman ve sıra kelimelerini kontrol ederek TRUE, FALSE ya da NOT GIVEN’a karar vermeyi öğreneceksin.","fa":"در این درس یاد می‌گیری یادداشت‌های یک متن تاریخی را با یک کلمه از متن کامل کنی و با بررسی کلمه‌های زمان و ترتیب بین TRUE، FALSE و NOT GIVEN تصمیم بگیری."},"objectiveGT":{"en":"In this lesson you will learn to match statements to five event adverts, using letters more than once, and to decide TRUE, FALSE or NOT GIVEN about the details of a course.","tr":"Bu derste harfleri birden fazla kullanarak ifadeleri beş etkinlik ilanıyla eşleştirmeyi ve bir kursun ayrıntıları hakkında TRUE, FALSE ya da NOT GIVEN’a karar vermeyi öğreneceksin.","fa":"در این درس یاد می‌گیری جمله‌ها را با پنج آگهی رویداد جور کنی، طوری که حرف‌ها بیش از یک بار بیایند، و درباره‌ی جزئیات یک دوره بین TRUE، FALSE و NOT GIVEN تصمیم بگیری."},"sessions":[["explain"],["drill"],["exit"]],"explain":{"title":{"en":"Reading Passage 1: the history of an invention","tr":"Reading Passage 1: bir icadın tarihi","fa":"Reading Passage 1: تاریخچه‌ی یک اختراع"},"objective":{"en":"In this lesson you will learn to complete notes on a history with one word from the passage, and to decide TRUE, FALSE or NOT GIVEN by checking words about time and order.","tr":"Bu derste bir tarih metni üzerine notları metinden tek kelimeyle tamamlamayı ve zaman ve sıra kelimelerini kontrol ederek TRUE, FALSE ya da NOT GIVEN’a karar vermeyi öğreneceksin.","fa":"در این درس یاد می‌گیری یادداشت‌های یک متن تاریخی را با یک کلمه از متن کامل کنی و با بررسی کلمه‌های زمان و ترتیب بین TRUE، FALSE و NOT GIVEN تصمیم بگیری."},"stats":[{"label":{"en":"Questions","tr":"Soru","fa":"سؤال"},"value":"13"},{"label":{"en":"Time","tr":"Süre","fa":"زمان"},"value":{"en":"20 min","tr":"20 dk","fa":"۲۰ دقیقه"}},{"label":{"en":"Words","tr":"Kelime","fa":"کلمه"},"value":"~750"}],"context":{"eyebrow":{"en":"1 The context","tr":"1 Bağlam","fa":"۱ بافت"},"head":{"en":"This exam: the tin can","tr":"Bu sınav: teneke kutu","fa":"این آزمون: قوطی کنسرو"},"intro":{"en":"History is one of the two most common Passage 1 subjects. The history of an object or a trade is told in time order, so dates and order words carry many of the answers.","tr":"Tarih, en sık çıkan iki Passage 1 konusundan biridir. Bir nesnenin ya da bir mesleğin tarihi zaman sırasıyla anlatılır; bu yüzden tarihler ve sıra kelimeleri cevapların çoğunu taşır.","fa":"تاریخ یکی از دو موضوع رایج‌تر Passage 1 است. تاریخچه‌ی یک شیء یا یک حرفه به ترتیب زمان گفته می‌شود، پس تاریخ‌ها و کلمه‌های ترتیب خیلی از جواب‌ها را دارند."},"technique":{"en":"2 The technique","tr":"2 Teknik","fa":"۲ تکنیک"},"labels":{"asks":{"en":"What this part is about","tr":"Bu kısım ne hakkında","fa":"این بخش درباره‌ی چیست"},"fields":{"en":"Headings you will see","tr":"Göreceğin başlıklar","fa":"عنوان‌هایی که می‌بینی"},"words":{"en":"Words that carry the answers","tr":"Cevabı taşıyan kelimeler","fa":"کلمه‌هایی که جواب را می‌آورند"},"a":{"en":"On the paper","tr":"Kâğıtta","fa":"روی برگه"},"b":{"en":"What you hear or read","tr":"Duyduğun ya da okuduğun","fa":"چیزی که می‌شنوی یا می‌خوانی"},"traps":{"en":"Traps","tr":"Tuzaklar","fa":"دام‌ها"},"example":{"en":"Example","tr":"Örnek","fa":"نمونه"},"ideas":{"en":"Ideas","tr":"Fikirler","fa":"ایده‌ها"}},"cards":[{"id":"x07-r1-ctx","exam":true,"patterns":["RA-history","PARA-cause"],"often":{"pattern":"RA-history","n":35,"of":120,"label":{"en":"Comes up often in the real exam: 35 of the last 120 passages","tr":"Gerçek sınavda sık çıkar: son 120 metnin 35’inde","fa":"در آزمون واقعی زیاد می‌آید: در ۳۵ متن از ۱۲۰ متنِ اخیر"}},"title":{"en":"The history of an everyday invention","tr":"Gündelik bir icadın tarihi","fa":"تاریخچه‌ی یک اختراع روزمره"},"asks":{"en":"A history in time order: the problem the invention solved, the first inventor, an improvement, early difficulties and dangers, and how it became cheap and common. Notes test the early part; statements test the later part.","tr":"Zaman sırasına göre bir tarih: icadın çözdüğü sorun, ilk mucit, bir iyileştirme, ilk zorluklar ve tehlikeler, nasıl ucuz ve yaygın hâle geldiği. Notlar ilk kısmı, ifadeler sonraki kısmı ölçer.","fa":"یک روایت تاریخی به ترتیب زمان: مشکلی که اختراع حل کرد، اولین مخترع، یک بهبود، سختی‌ها و خطرهای اولیه و اینکه چطور ارزان و همه‌گیر شد. یادداشت‌ها بخش اول و جمله‌ها بخش بعدی را می‌سنجند."},"fields":["The problem","The first method","An improvement","First customers","Early difficulties","Dangers","How it became cheap"],"words":[{"a":"preserve","b":"keep food from going bad","tr":"korumak, saklamak","fa":"نگه‌داری کردن"},{"a":"offered a prize","b":"promised a reward to anyone who","tr":"ödül vaat etti","fa":"جایزه تعیین کرد"},{"a":"sealed","b":"closed tightly","tr":"sıkıca kapatılmış","fa":"دربسته، مهروموم‌شده"},{"a":"did not know why","b":"it was only later that people understood","tr":"nedenini bilmiyordu","fa":"نمی‌دانست چرا"},{"a":"weakness","b":"problem / disadvantage","tr":"zayıflık","fa":"ضعف"},{"a":"customer","b":"buyer / bought large quantities","tr":"müşteri","fa":"مشتری"},{"a":"by hand","b":"not by machine","tr":"elle","fa":"با دست"},{"a":"not until","b":"only after / much later","tr":"... e kadar değil","fa":"تا ... نه"},{"a":"some historians believe","b":"it is possible / still debated","tr":"bazı tarihçiler inanıyor","fa":"بعضی مورخ‌ها معتقدند"},{"a":"an expensive luxury","b":"only the rich could afford it","tr":"pahalı bir lüks","fa":"تجملی گران"},{"a":"prices fell sharply","b":"became much cheaper","tr":"fiyatlar hızla düştü","fa":"قیمت‌ها به‌شدت پایین آمد"},{"a":"transformed","b":"changed completely","tr":"tamamen değiştirdi","fa":"دگرگون کرد"}],"traps":[{"en":"Order words: \"not until many years after\" means the second thing came much later, not at the same time.","tr":"Sıra kelimeleri: \"uzun yıllar sonrasına kadar değil\", ikinci şeyin aynı anda değil çok sonra geldiği anlamına gelir.","fa":"کلمه‌های ترتیب: «تا سال‌ها بعد نه» یعنی دومی خیلی دیرتر آمد، نه هم‌زمان."},{"en":"\"At first\" and \"remained\" describe one period only. A statement that says \"from the beginning\" or \"always\" may be FALSE.","tr":"\"At first\" ve \"remained\" yalnızca bir dönemi anlatır. \"Baştan beri\" ya da \"her zaman\" diyen bir ifade FALSE olabilir.","fa":"«at first» و «remained» فقط یک دوره را توصیف می‌کنند. جمله‌ای که می‌گوید «از همان اول» یا «همیشه» ممکن است FALSE باشد."},{"en":"Notes with ONE WORD ONLY: \"a spoon and a ___\" needs only the noun, copied exactly.","tr":"ONE WORD ONLY notlar: \"a spoon and a ___\" yalnızca ismi ister, aynen kopyalanmış.","fa":"یادداشت ONE WORD ONLY: «a spoon and a ___» فقط اسم را می‌خواهد، دقیقاً کپی‌شده."}],"example":{"text":"\"The first bicycles had no brakes. Brakes became common only in the 1890s, thirty years after the first models.\"","item":"Statement: Bicycles had brakes from the start.","answer":"FALSE","why":{"en":"\"The first bicycles had no brakes\" contradicts \"from the start\".","tr":"\"İlk bisikletlerin freni yoktu\", \"baştan beri\" ile çelişiyor.","fa":"«اولین دوچرخه‌ها ترمز نداشتند» با «از همان اول» تناقض دارد."}}},{"id":"RA-history-p1","ctx":["RA-history"],"title":{"en":"The history of an object, a place or a trade","tr":"Bir nesnenin, yerin ya da ticaretin tarihi","fa":"تاریخچه‌ی یک شیء، یک مکان یا یک تجارت"},"asks":{"en":"The history of an everyday object, a trade, a building or a discovery: where it began, who developed it, how it spread and how it changed. Statements test dates, people and causes; the notes follow the order of events.","tr":"Gündelik bir nesnenin, bir ticaretin, bir binanın ya da bir keşfin tarihi: nerede başladığı, kimin geliştirdiği, nasıl yayıldığı ve nasıl değiştiği. İfadeler tarihleri, kişileri ve nedenleri sınar; notlar olayların sırasını izler.","fa":"تاریخچه‌ی یک شیء روزمره، یک تجارت، یک ساختمان یا یک کشف: از کجا شروع شد، چه کسی آن را توسعه داد، چطور گسترش یافت و چطور تغییر کرد. جمله‌ها تاریخ‌ها، آدم‌ها و علت‌ها را می‌سنجند؛ یادداشت‌ها ترتیب رویدادها را دنبال می‌کنند."},"fields":["The material was first used by local farmers.","The design changed in the 18th century.","The inventor made a lot of money from it.","Notes: Origins · Early uses · Spread · Later developments"],"words":[{"a":"invented","b":"developed / came up with","tr":"icat etti","fa":"اختراع کرد"},{"a":"popular","b":"in demand / widely used","tr":"rağbet gören","fa":"پرطرفدار"},{"a":"spread","b":"was taken to / reached","tr":"yayıldı","fa":"گسترش یافت"},{"a":"expensive","b":"costly / only the rich could afford it","tr":"pahalı","fa":"گران"},{"a":"replaced","b":"took the place of / gave way to","tr":"yerini aldı","fa":"جایش را گرفت"},{"a":"soon","b":"within a few years / shortly afterwards","tr":"kısa sürede","fa":"به‌زودی"},{"a":"earlier than","b":"predates / came before","tr":"... -den önce","fa":"زودتر از"},{"a":"made money","b":"profited from / earned","tr":"para kazandı","fa":"پول درآورد"},{"a":"the government","b":"the authorities / the state","tr":"hükümet","fa":"دولت"},{"a":"exported","b":"sold abroad","tr":"ihraç etti","fa":"صادر کرد"},{"a":"remained","b":"continued / was still","tr":"kaldı, sürdü","fa":"باقی ماند"},{"a":"by hand","b":"without machines / manually","tr":"elle","fa":"با دست"}],"traps":[{"en":"NOT GIVEN when the text names a person but says nothing about their money, motives or feelings.","tr":"Metin bir kişinin adını verip parası, amacı ya da duyguları hakkında hiçbir şey söylemiyorsa: NOT GIVEN.","fa":"وقتی متن اسم کسی را می‌آورد ولی درباره‌ی پول، انگیزه یا احساسش چیزی نمی‌گوید: NOT GIVEN."},{"en":"Dates close together: \"first described in 1565, made in factories from 1795\". Match the date to the event.","tr":"Yakın tarihler: \"ilk kez 1565’te tarif edildi, 1795’ten itibaren fabrikada üretildi\". Tarihi olayla eşleştir.","fa":"تاریخ‌های نزدیک هم: «اولین بار ۱۵۶۵ توصیف شد، از ۱۷۹۵ در کارخانه ساخته شد». تاریخ را با رویداد جور کن."}],"example":{"text":"Glass windows were known in Roman times, but for centuries only churches and the very rich could afford them. In 1696 England introduced a tax on windows, and many owners bricked theirs up. The tax was finally abolished in 1851.","item":"Notes: Window tax: introduced in ___   (ONE WORD AND/OR A NUMBER)","answer":"1696","why":{"en":"1696 is when it was introduced; 1851 is when it was abolished.","tr":"1696 getirildiği yıl; 1851 kaldırıldığı yıl.","fa":"۱۶۹۶ سال وضع مالیات است؛ ۱۸۵۱ سال لغو آن."}},"track":"academic","general":true,"patterns":["RA-history"],"often":{"pattern":"RA-history","n":35,"of":120,"label":{"en":"Comes up often in the real exam: 35 of the last 120 passages","tr":"Gerçek sınavda sık çıkar: son 120 metnin 35’inde","fa":"در آزمون واقعی زیاد می‌آید: در ۳۵ متن از ۱۲۰ متنِ اخیر"}}}]},"points":[{"eyebrow":{"en":"In the exam","tr":"Sınavda","fa":"در آزمون"},"head":{"en":"Notes first, then six statements","tr":"Önce notlar, sonra altı ifade","fa":"اول یادداشت‌ها، بعد شش جمله"},"body":{"en":"Questions 1-7: complete notes with ONE WORD ONLY from the passage. Questions 8-13: TRUE, FALSE or NOT GIVEN. Both sets follow the order of the passage. Spend about 20 minutes; there is no extra time to copy answers.","tr":"Soru 1-7: notları metinden ONE WORD ONLY ile tamamla. Soru 8-13: TRUE, FALSE ya da NOT GIVEN. İki grup da metnin sırasını izler. Yaklaşık 20 dakika ayır; cevapları aktarmak için ek süre yok.","fa":"سؤال‌های ۱ تا ۷: یادداشت‌ها را با ONE WORD ONLY از متن کامل کن. سؤال‌های ۸ تا ۱۳: TRUE، FALSE یا NOT GIVEN. هر دو گروه ترتیب متن را دنبال می‌کنند. حدود ۲۰ دقیقه وقت بگذار؛ زمان اضافه برای انتقال جواب‌ها نیست."}},{"eyebrow":{"en":"The method","tr":"Yöntem","fa":"روش"},"head":{"en":"Four steps","tr":"Dört adım","fa":"چهار قدم"},"steps":[{"en":"Use names and dates in the notes to find the right paragraph.","tr":"Doğru paragrafı bulmak için notlardaki isimleri ve tarihleri kullan.","fa":"با اسم‌ها و تاریخ‌های یادداشت پاراگراف درست را پیدا کن."},{"en":"Copy one word exactly; check whether the gap needs a singular or a plural.","tr":"Tek kelimeyi aynen kopyala; boşluğun tekil mi çoğul mu istediğine bak.","fa":"یک کلمه را دقیقاً کپی کن؛ ببین جای خالی مفرد می‌خواهد یا جمع."},{"en":"For each statement, find its sentence and check the time words: at first, until, later, from the beginning.","tr":"Her ifade için cümlesini bul ve zaman kelimelerini kontrol et: at first, until, later, from the beginning.","fa":"برای هر جمله، جمله‌ی متن را پیدا کن و کلمه‌های زمان را چک کن: at first، until، later، from the beginning."},{"en":"If the text gives a fact near the statement but not about it, choose NOT GIVEN.","tr":"Metin ifadeye yakın ama onunla ilgili olmayan bir bilgi veriyorsa NOT GIVEN’ı seç.","fa":"اگر متن اطلاعاتی نزدیک به جمله می‌دهد اما درباره‌ی خود آن نیست، NOT GIVEN را انتخاب کن."}]},{"eyebrow":{"en":"The trap","tr":"Tuzak","fa":"دام"},"head":{"en":"FALSE or NOT GIVEN?","tr":"FALSE mı NOT GIVEN mı?","fa":"FALSE یا NOT GIVEN؟"},"table":{"headers":{"en":["The text","The answer"],"tr":["Metin","Cevap"],"fa":["متن","جواب"]},"rows":[["says the same thing in other words","TRUE"],["says the opposite, or a different fact on the same point","FALSE"],["says nothing about this point","NOT GIVEN"]]}}],"example":{"eyebrow":{"en":"Worked example","tr":"Çözümlü örnek","fa":"مثال حل‌شده"},"head":{"en":"One statement, step by step","tr":"Bir ifade, adım adım","fa":"یک جمله، قدم به قدم"},"instruction":"Do the following statements agree with the information given in the passage?","text":"\"The first telephones were rented, not sold. It was not until the 1920s that most families owned one.\"","item":"Statement: Families could buy telephones as soon as they were invented.","answer":"FALSE","walk":[{"en":"Find the place: the sentence about how the first telephones were supplied.","tr":"Yeri bul: ilk telefonların nasıl sağlandığıyla ilgili cümle.","fa":"جایش را پیدا کن: جمله‌ای درباره‌ی اینکه اولین تلفن‌ها چطور عرضه می‌شدند."},{"en":"Compare: \"rented, not sold\" at first.","tr":"Karşılaştır: ilk başta \"kiralanıyordu, satılmıyordu\".","fa":"مقایسه کن: اول «اجاره داده می‌شد، فروخته نمی‌شد»."},{"en":"That contradicts \"could buy as soon as they were invented\": FALSE.","tr":"Bu, \"icat edilir edilmez satın alınabiliyordu\" ile çelişiyor: FALSE.","fa":"این با «همان اول اختراع می‌شد خرید» تناقض دارد: FALSE."}]},"quick":{"prompt":"Text: \"The bridge opened in 1885.\" Statement: \"The bridge was the longest in the country when it opened.\" TRUE, FALSE or NOT GIVEN?","options":["TRUE","FALSE","NOT GIVEN"],"correct":2,"why":{"en":"The year is given; its length compared with others is not.","tr":"Yıl veriliyor; diğerlerine göre uzunluğu verilmiyor.","fa":"سال آمده؛ طولش در مقایسه با بقیه نیامده."}},"remember":{"en":"Copy one word exactly for notes, and check every time word in a statement against the passage.","tr":"Notlar için bir kelimeyi aynen kopyala ve bir ifadedeki her zaman kelimesini metinle karşılaştır.","fa":"برای یادداشت یک کلمه را دقیقاً کپی کن و هر کلمه‌ی زمان در جمله را با متن بسنج."},"type":"explain","id":"c-x07-r1-e","course":"ielts-exams","exam":"exam-07","unit":"x07-r1"},"drill":{"type":"drill","skill":"reading","part":"Academic Reading Passage 1","title":{"en":"The tin can: a history in a container","tr":"Teneke kutu: bir kabın içindeki tarih","fa":"قوطی کنسرو: تاریخی در یک ظرف"},"timed":20,"ctx":["RA-history"],"intro":"You should spend about 20 minutes on Questions 1-13, which are based on Reading Passage 1 below.","passage":"The tin can: a history in a container\n\nFew objects are as ordinary as the tin can. Billions are opened every year, and most people give them no more thought than they give to a cardboard box. Yet the can was once a remarkable invention, and its story says a great deal about war, science and the changing diet of ordinary people.\n\nThe problem it solved was an old one. For most of history, food could be kept only by drying, salting, smoking or pickling it, and all of these methods changed its taste and texture. Armies and navies suffered most. Soldiers on long campaigns and sailors on long voyages lived on hard biscuits and salted meat, and many fell ill from a lack of fresh food. On some long voyages, more sailors died from disease than from storms or battles, and military leaders were well aware that an army which could not be fed could not fight.\n\nAt the end of the eighteenth century, the French government offered a large prize to anyone who could find a better way of preserving food for its armies. The prize was eventually won by Nicolas Appert, a confectioner from Paris, who had spent years experimenting in his kitchen. His method was to place food in glass jars, seal them tightly with cork and wax, and then heat them in boiling water for several hours. Food treated in this way stayed edible for months. Samples sent to sea with the navy were opened after long periods and found to be in good condition, and in 1810 Appert published a book describing his methods so that others could use them.\n\nAppert did not know why his method worked. It was only decades later, after the work of scientists such as Louis Pasteur, that people understood that heat kills the tiny organisms that make food go bad. Appert simply knew from experience that it did. His jars, however, had one serious weakness: glass breaks easily, especially on the deck of a ship or the back of a cart.\n\nThe answer came from England. In 1810, a patent was granted for preserving food in containers made of iron coated with a thin layer of tin, which stopped the metal from rusting. Within a few years, a factory in London was producing tinned meat and vegetables. Its first important customer was the navy, which bought large quantities for ships setting out on long voyages, and explorers soon followed, taking tinned food with them on journeys to the Arctic and beyond.\n\nEarly cans were nothing like the ones we know. They were heavy, thick-walled containers, each one made and sealed by hand. A skilled worker could produce only about sixty in a day. Nor was it easy to get into them. The first cans came with instructions to open them with a hammer and a chisel, and the can opener was not invented until almost half a century after the can itself.\n\nThere were also dangers. The cans were sealed with solder that contained lead, and some historians believe that lead from food cans may have contributed to the illness of sailors on long expeditions in the nineteenth century. The evidence is still debated, but the risk was real enough that lead solder was eventually abandoned.\n\nFor several decades, tinned food remained an expensive luxury, bought mainly by the armed forces and the wealthy. What changed this was demand on an enormous scale. Demand grew greatly during wars, when armies needed to feed hundreds of thousands of soldiers far from home. At the same time, new machines transformed production. By the late nineteenth century, factories could make thousands of cans an hour, and prices fell sharply.\n\nBy the early twentieth century, tinned fruit, fish and soup had become part of the ordinary family diet in many countries. The can had changed not only what armies ate, but what was available in every local shop, in every season of the year.\n\nToday, cans are made of thin steel or aluminium, sealed by machines at astonishing speed, and lined with coatings that protect both the food and the metal. Some food writers look down on tinned food as a poor substitute for fresh ingredients. Nutritionists are less dismissive. Because fruit and vegetables are usually canned within hours of being picked, some of them keep their vitamins surprisingly well, sometimes better than fresh produce that has spent days being transported and stored. For an invention that began with a prize, a kitchen and a hammer, the can has had a remarkably long life.","groups":[{"instruction":"Questions 1-7. Complete the notes below. Choose ONE WORD ONLY from the passage for each answer. Write your answers in boxes 1-7 on your answer sheet.","qtype":"note","notesTitle":"The early history of tinned food","questions":[{"n":1,"kind":"gap","prompt":"Appert · put food into glass ___","accept":["jars"],"limit":1,"evidence":"place food in glass jars","why":{"en":"\"His method was to place food in glass jars.\" Plural.","tr":"\"Yöntemi yiyeceği cam kavanozlara koymaktı.\" Çoğul.","fa":"«روش او این بود که غذا را در شیشه‌های دربسته بگذارد». جمع."},"trap":["TR-plural"]},{"n":2,"kind":"gap","prompt":"Appert · heated the containers in boiling ___","accept":["water"],"limit":1,"evidence":"heat them in boiling water for several hours","why":{"en":"\"Then heat them in boiling water for several hours.\"","tr":"\"Sonra onları birkaç saat kaynar suda ısıtmak.\"","fa":"«بعد آن‌ها را چند ساعت در آب جوش گرم کند»."},"trap":["TR-paraphrase"]},{"n":3,"kind":"gap","prompt":"1810 patent · containers made of tin-coated ___","accept":["iron"],"limit":1,"evidence":"containers made of iron coated with a thin layer of tin","why":{"en":"\"Iron coated with a thin layer of tin\" = tin-coated iron.","tr":"\"İnce bir kalay tabakasıyla kaplı demir\" = kalay kaplı demir.","fa":"«آهنی که با لایه‌ی نازکی از قلع پوشانده شده» یعنی آهن قلع‌اندود."},"trap":["TR-paraphrase"]},{"n":4,"kind":"gap","prompt":"First important customer: the ___","accept":["navy"],"limit":1,"evidence":"Its first important customer was the navy","why":{"en":"\"Its first important customer was the navy.\" Explorers came later.","tr":"\"İlk önemli müşterisi donanmaydı.\" Kâşifler sonra geldi.","fa":"«اولین مشتری مهمش نیروی دریایی بود». کاشف‌ها بعداً آمدند."},"trap":["TR-paraphrase"]},{"n":5,"kind":"gap","prompt":"Early cans · opened with a hammer and a ___","accept":["chisel"],"limit":1,"evidence":"open them with a hammer and a chisel","why":{"en":"\"Instructions to open them with a hammer and a chisel.\" \"hammer\" is printed.","tr":"\"Onları bir çekiç ve bir keskiyle açma talimatı.\" \"hammer\" yazılı.","fa":"«دستورِ باز کردنشان با چکش و قلم». «hammer» چاپ شده."},"trap":["TR-limit"]},{"n":6,"kind":"gap","prompt":"Dangers · solder containing ___","accept":["lead"],"limit":1,"evidence":"solder that contained lead","why":{"en":"\"The cans were sealed with solder that contained lead.\"","tr":"\"Kutular kurşun içeren lehimle kapatılıyordu.\"","fa":"«قوطی‌ها با لحیمی بسته می‌شدند که سرب داشت»."},"trap":["TR-paraphrase"]},{"n":7,"kind":"gap","prompt":"Explorers · took tinned food on journeys to the ___","accept":["Arctic"],"limit":1,"evidence":"on journeys to the Arctic and beyond","why":{"en":"\"Explorers soon followed, taking tinned food with them on journeys to the Arctic and beyond.\"","tr":"\"Kâşifler de kısa sürede bunu izledi; konserveyi Arktik’e ve ötesine yolculuklarda yanlarında götürdüler.\"","fa":"«کاشف‌ها هم زود دنبالش رفتند و در سفر به قطب شمال و فراتر از آن غذای کنسروی با خود بردند»."},"trap":["TR-paraphrase"]}]},{"instruction":"Questions 8-13. Do the following statements agree with the information given in Reading Passage 1? In boxes 8-13 on your answer sheet, write TRUE if the statement agrees with the information, FALSE if the statement contradicts the information, NOT GIVEN if there is no information on this.","qtype":"tfng","questions":[{"n":8,"kind":"tfng","prompt":"The can opener was invented at about the same time as the can.","correct":"FALSE","evidence":"the can opener was not invented until almost half a century after the can itself","why":{"en":"\"Not invented until almost half a century after the can itself.\"","tr":"\"Kutunun kendisinden neredeyse yarım yüzyıl sonrasına kadar icat edilmedi.\"","fa":"«تا تقریباً نیم قرن بعد از خودِ قوطی اختراع نشد»."},"trap":["TR-NGvsF"]},{"n":9,"kind":"tfng","prompt":"Each early can was made and sealed by hand.","correct":"TRUE","evidence":"each one made and sealed by hand","why":{"en":"\"Heavy, thick-walled containers, each one made and sealed by hand.\"","tr":"\"Ağır, kalın duvarlı kaplar, her biri elle yapılıp kapatılmış.\"","fa":"«ظرف‌هایی سنگین و دیواره‌کلفت که هر کدام با دست ساخته و بسته می‌شد»."},"trap":["TR-paraphrase"]},{"n":10,"kind":"tfng","prompt":"From the beginning, tinned food was cheaper than fresh food.","correct":"FALSE","evidence":"tinned food remained an expensive luxury","why":{"en":"\"For several decades, tinned food remained an expensive luxury.\"","tr":"\"Birkaç on yıl boyunca konserve pahalı bir lüks olarak kaldı.\"","fa":"«چند دهه، غذای کنسروی تجملی گران ماند»."},"trap":["TR-NGvsF"]},{"n":11,"kind":"tfng","prompt":"Lead from cans definitely caused illness among sailors on long expeditions.","correct":"FALSE","evidence":"some historians believe that lead from food cans may have contributed","why":{"en":"Only \"some historians believe\" it \"may have contributed\", and \"the evidence is still debated\". \"Definitely\" contradicts this.","tr":"Yalnızca \"bazı tarihçiler\" bunun \"katkıda bulunmuş olabileceğine inanıyor\" ve \"kanıt hâlâ tartışmalı\". \"Kesinlikle\" bununla çelişiyor.","fa":"فقط «بعضی مورخ‌ها معتقدند» که «ممکن است نقش داشته» و «شواهد هنوز محل بحث است». «قطعاً» با این تناقض دارد."},"trap":["TR-hedge","TR-NGvsF"]},{"n":12,"kind":"tfng","prompt":"By the late nineteenth century, machines made cans much more quickly.","correct":"TRUE","evidence":"factories could make thousands of cans an hour","why":{"en":"A worker once made sixty a day; by the late nineteenth century \"factories could make thousands of cans an hour\".","tr":"Bir işçi eskiden günde altmış tane yapıyordu; on dokuzuncu yüzyılın sonunda \"fabrikalar saatte binlerce kutu yapabiliyordu\".","fa":"یک کارگر روزی شصت تا می‌ساخت؛ اواخر قرن نوزدهم «کارخانه‌ها ساعتی هزاران قوطی می‌ساختند»."},"trap":["TR-paraphrase"]},{"n":13,"kind":"tfng","prompt":"Most families in Britain owned a can opener by 1900.","correct":"NOT GIVEN","evidence":"tinned fruit, fish and soup had become part of the ordinary family diet","why":{"en":"The text says tinned food became part of the family diet, but says nothing about how many families owned a can opener.","tr":"Metin konservenin aile beslenmesinin bir parçası olduğunu söylüyor ama kaç ailenin konserve açacağı olduğundan söz etmiyor.","fa":"متن می‌گوید غذای کنسروی جزو غذای خانواده‌ها شد، اما درباره‌ی تعداد خانواده‌هایی که دربازکن داشتند چیزی نمی‌گوید."},"trap":["TR-NGvsF"]}]}],"id":"c-x07-r1-d","course":"ielts-exams","exam":"exam-07","unit":"x07-r1"},"exit":{"type":"exit","items":[{"tests":"word","point":1,"prompt":"\"The method was to preserve food in sealed jars.\" To preserve food is to...","options":["cook it quickly","stop it going bad","sell it abroad"],"correct":1,"why":{"en":"Preserve = keep in good condition for a long time.","tr":"Preserve = uzun süre iyi durumda tutmak.","fa":"preserve یعنی برای مدت طولانی سالم نگه داشتن."}},{"tests":"paraphrase","point":3,"prompt":"A statement says \"at about the same time\". Which words in a passage would make it FALSE?","options":["not until almost fifty years later","in the same year","shortly afterwards"],"correct":0,"why":{"en":"Fifty years later is not the same time.","tr":"Elli yıl sonra aynı zaman değildir.","fa":"پنجاه سال بعد یعنی هم‌زمان نیست."}},{"tests":"method","point":2,"prompt":"Note: \"sealed with cork and ___\" (ONE WORD ONLY). The passage says \"seal them tightly with cork and wax\". You write...","options":["cork and wax","tightly","wax"],"correct":2,"why":{"en":"\"cork and\" is printed; copy only the missing noun.","tr":"\"cork and\" yazılı; yalnızca eksik ismi kopyala.","fa":"«cork and» چاپ شده؛ فقط اسم جاافتاده را کپی کن."}},{"tests":"trap","point":3,"prompt":"Text: \"Some experts think the factory closed because of a fire.\" Statement: \"The factory definitely closed because of a fire.\"","options":["TRUE","FALSE","NOT GIVEN"],"correct":1,"why":{"en":"\"Some experts think\" is uncertain; \"definitely\" contradicts it.","tr":"\"Bazı uzmanlar düşünüyor\" belirsiz; \"kesinlikle\" bununla çelişiyor.","fa":"«بعضی کارشناس‌ها فکر می‌کنند» قطعی نیست؛ «قطعاً» با آن تناقض دارد."}}],"id":"c-x07-r1-x","course":"ielts-exams","exam":"exam-07","unit":"x07-r1"},"gt":{"explain":{"title":{"en":"GT Reading Section 1: adverts and course information","tr":"GT Reading Section 1: ilanlar ve kurs bilgisi","fa":"GT Reading Section 1: آگهی‌ها و اطلاعات دوره"},"objective":{"en":"In this lesson you will learn to match statements to five event adverts, using letters more than once, and to decide TRUE, FALSE or NOT GIVEN about the details of a course.","tr":"Bu derste harfleri birden fazla kullanarak ifadeleri beş etkinlik ilanıyla eşleştirmeyi ve bir kursun ayrıntıları hakkında TRUE, FALSE ya da NOT GIVEN’a karar vermeyi öğreneceksin.","fa":"در این درس یاد می‌گیری جمله‌ها را با پنج آگهی رویداد جور کنی، طوری که حرف‌ها بیش از یک بار بیایند، و درباره‌ی جزئیات یک دوره بین TRUE، FALSE و NOT GIVEN تصمیم بگیری."},"stats":[{"label":{"en":"Questions","tr":"Soru","fa":"سؤال"},"value":"14"},{"label":{"en":"Texts","tr":"Metin","fa":"متن"},"value":"2"},{"label":{"en":"Time","tr":"Süre","fa":"زمان"},"value":{"en":"about 15 min","tr":"yaklaşık 15 dk","fa":"حدود ۱۵ دقیقه"}}],"context":{"eyebrow":{"en":"1 The context","tr":"1 Bağlam","fa":"۱ بافت"},"head":{"en":"This exam: weekend events and a driving course","tr":"Bu sınav: hafta sonu etkinlikleri ve bir sürüş kursu","fa":"این آزمون: رویدادهای آخر هفته و یک دوره‌ی رانندگی"},"intro":{"en":"Adverts for events, courses and places are the most common GT Section 1 texts. They are short and full of practical details: prices, ages, times, rules. Read the statements first, then scan for the matching detail.","tr":"Etkinlikler, kurslar ve yerler için ilanlar en sık çıkan GT Section 1 metinleridir. Kısadırlar ve pratik ayrıntılarla doludurlar: fiyatlar, yaşlar, saatler, kurallar. Önce ifadeleri oku, sonra eşleşen ayrıntıyı tara.","fa":"آگهی رویدادها، دوره‌ها و جاها رایج‌ترین متن‌های GT Section 1 هستند. کوتاه‌اند و پر از جزئیات عملی: قیمت، سن، ساعت، قانون. اول جمله‌ها را بخوان و بعد دنبال جزئیاتی بگرد که جور است."},"technique":{"en":"2 The technique","tr":"2 Teknik","fa":"۲ تکنیک"},"labels":{"asks":{"en":"What this part is about","tr":"Bu kısım ne hakkında","fa":"این بخش درباره‌ی چیست"},"fields":{"en":"Headings you will see","tr":"Göreceğin başlıklar","fa":"عنوان‌هایی که می‌بینی"},"words":{"en":"Words that carry the answers","tr":"Cevabı taşıyan kelimeler","fa":"کلمه‌هایی که جواب را می‌آورند"},"a":{"en":"On the paper","tr":"Kâğıtta","fa":"روی برگه"},"b":{"en":"What you hear or read","tr":"Duyduğun ya da okuduğun","fa":"چیزی که می‌شنوی یا می‌خوانی"},"traps":{"en":"Traps","tr":"Tuzaklar","fa":"دام‌ها"},"example":{"en":"Example","tr":"Örnek","fa":"نمونه"},"ideas":{"en":"Ideas","tr":"Fikirler","fa":"ایده‌ها"}},"cards":[{"id":"x07-r1gt-ctx","exam":true,"patterns":["GT1-ads"],"often":{"pattern":"GT1-ads","n":24,"of":65,"label":{"en":"Comes up often in the real exam: 24 of the last 65 texts","tr":"Gerçek sınavda sık çıkar: son 65 metnin 24’ünde","fa":"در آزمون واقعی زیاد می‌آید: در ۲۴ متن از ۶۵ متنِ اخیر"}},"title":{"en":"Event adverts and course information","tr":"Etkinlik ilanları ve kurs bilgisi","fa":"آگهی رویدادها و اطلاعات یک دوره"},"asks":{"en":"Text 1 is five short adverts for events, A-E: you decide which event each statement describes. Text 2 is information about a course: you decide TRUE, FALSE or NOT GIVEN.","tr":"Metin 1 etkinlikler için beş kısa ilandır, A-E: her ifadenin hangi etkinliği anlattığına karar verirsin. Metin 2 bir kurs hakkında bilgidir: TRUE, FALSE ya da NOT GIVEN’a karar verirsin.","fa":"متن ۱ پنج آگهی کوتاه برای رویدادهاست، A تا E: تصمیم می‌گیری هر جمله کدام رویداد را توصیف می‌کند. متن ۲ اطلاعاتی درباره‌ی یک دوره است: بین TRUE، FALSE و NOT GIVEN تصمیم می‌گیری."},"fields":["Price","Age","Weather","Dogs","Tickets","Who the course is for","Cost","Insurance","Certificate"],"words":[{"a":"free entry","b":"no charge to get in","tr":"ücretsiz giriş","fa":"ورود رایگان"},{"a":"adults only","b":"not for children or teenagers","tr":"yalnızca yetişkinler","fa":"فقط بزرگسالان"},{"a":"may be cancelled","b":"might not happen","tr":"iptal edilebilir","fa":"ممکن است لغو شود"},{"a":"book in advance","b":"buy tickets beforehand","tr":"önceden rezervasyon","fa":"از قبل رزرو کردن"},{"a":"make something","b":"create something with your own hands","tr":"bir şey yapmak","fa":"چیزی ساختن"},{"a":"dogs welcome","b":"you can bring your dog","tr":"köpekler kabul edilir","fa":"سگ مجاز است"},{"a":"open to anyone","b":"everyone can join","tr":"herkese açık","fa":"برای همه آزاد"},{"a":"reduced price","b":"a discount / pay less","tr":"indirimli fiyat","fa":"قیمت با تخفیف"},{"a":"some","b":"not all","tr":"bazı","fa":"بعضی"},{"a":"certificate","b":"a document to show you completed it","tr":"sertifika","fa":"گواهی"},{"a":"premium","b":"the price you pay for insurance","tr":"sigorta primi","fa":"حق بیمه"},{"a":"in advance","b":"beforehand","tr":"önceden","fa":"از قبل"}],"traps":[{"en":"\"Some companies...\" does not mean all of them. A statement with \"all\" or \"every\" is then FALSE.","tr":"\"Bazı şirketler...\" hepsi demek değildir. \"All\" ya da \"every\" içeren bir ifade o zaman FALSE olur.","fa":"«بعضی شرکت‌ها...» یعنی همه نه. جمله‌ای با «all» یا «every» در این حالت FALSE است."},{"en":"A word in the wrong advert: one advert may mention children because they get in free; another may say it is not suitable for them.","tr":"Yanlış ilandaki bir kelime: bir ilan çocuklardan ücretsiz girdikleri için söz edebilir; bir başkası onlara uygun olmadığını söyleyebilir.","fa":"کلمه در آگهی اشتباه: ممکن است یک آگهی از بچه‌ها حرف بزند چون مجانی وارد می‌شوند و آگهی دیگری بگوید برایشان مناسب نیست."}],"example":{"text":"\"F  Garden Open Day: free for members, £4 for everyone else. Sorry, no dogs except assistance dogs.\"","item":"Statement: Anyone can bring a dog to the Garden Open Day.","answer":"FALSE","why":{"en":"\"No dogs except assistance dogs\" contradicts \"anyone can bring a dog\".","tr":"\"Yardımcı köpekler dışında köpek yok\", \"herkes köpek getirebilir\" ile çelişiyor.","fa":"«سگ ممنوع، به‌جز سگ‌های راهنما» با «هر کسی می‌تواند سگ بیاورد» تناقض دارد."}}},{"id":"GT1-ads","ctx":["GT1-ads"],"title":{"en":"Adverts and listings","tr":"İlanlar ve listeler","fa":"آگهی‌ها و فهرست‌ها"},"asks":{"en":"Short adverts or listings A-F for courses, events, campsites, tours or clubs. Questions ask which advert mentions a fact, or whether a statement is TRUE, FALSE or NOT GIVEN.","tr":"Kurslar, etkinlikler, kamp alanları, turlar ya da kulüpler için A-F harfli kısa ilanlar veya listeler. Sorular hangi ilanın bir bilgiden söz ettiğini ya da bir ifadenin TRUE, FALSE veya NOT GIVEN olduğunu sorar.","fa":"آگهی‌ها یا فهرست‌های کوتاه A تا F برای کلاس‌ها، رویدادها، کمپ‌ها، تورها یا باشگاه‌ها. سؤال‌ها می‌پرسند کدام آگهی به یک نکته اشاره می‌کند، یا یک جمله TRUE، FALSE یا NOT GIVEN است."},"fields":["Which course is suitable for complete beginners?","Which event takes place outdoors?","Which campsite allows dogs?","Booking is required for all tours."],"words":[{"a":"suitable for beginners","b":"no experience needed","tr":"yeni başlayanlara uygun","fa":"مناسب مبتدی‌ها"},{"a":"free of charge","b":"at no cost / complimentary","tr":"ücretsiz","fa":"رایگان"},{"a":"booking essential","b":"places must be reserved","tr":"rezervasyon şart","fa":"رزرو الزامی"},{"a":"reduced price","b":"discount / 20% off","tr":"indirimli fiyat","fa":"قیمت با تخفیف"},{"a":"family-friendly","b":"children welcome","tr":"aileye uygun","fa":"مناسب خانواده"},{"a":"outdoors","b":"in the open air","tr":"açık havada","fa":"در فضای باز"},{"a":"pets allowed","b":"dogs welcome","tr":"evcil hayvan kabul edilir","fa":"ورود حیوان خانگی آزاد"},{"a":"on site","b":"at the campsite itself","tr":"tesis içinde","fa":"در خود محل"},{"a":"equipment provided","b":"everything supplied","tr":"ekipman sağlanır","fa":"تجهیزات داده می‌شود"},{"a":"refundable","b":"money back if you cancel","tr":"iade edilebilir","fa":"قابل استرداد"},{"a":"weekly","b":"once a week","tr":"haftalık","fa":"هفتگی"},{"a":"within walking distance","b":"nearby / a short walk away","tr":"yürüme mesafesinde","fa":"با پای پیاده نزدیک"}],"traps":[{"en":"Matching: two adverts mention dogs, but only one allows them. Read the whole line.","tr":"Eşleştirme: iki ilan köpeklerden söz eder ama yalnızca biri izin verir. Satırın tamamını oku.","fa":"جورکردن: دو آگهی از سگ حرف می‌زنند، ولی فقط یکی اجازه می‌دهد. کل خط را بخوان."},{"en":"\"Free\" in one advert may mean free parking, not free entry.","tr":"Bir ilandaki \"free\" giriş değil, ücretsiz otopark anlamına gelebilir.","fa":"«free» در یک آگهی شاید یعنی پارکینگ رایگان، نه ورود رایگان."}],"example":{"text":"C  Lakeside Campsite. Quiet site by the water. Sorry, no dogs. Shop on site.\nD  Hilltop Farm Camping. Families and well-behaved pets welcome. Nearest shop 2 km.","item":"Which campsite allows dogs?","answer":"D","why":{"en":"Both mention dogs or pets. C says \"no dogs\"; D says \"pets welcome\".","tr":"İkisi de köpek ya da evcil hayvandan söz ediyor. C \"köpek yok\", D \"evcil hayvanlar kabul\" diyor.","fa":"هر دو از سگ یا حیوان خانگی حرف می‌زنند. C می‌گوید «سگ ممنوع»؛ D می‌گوید «حیوان خانگی پذیرفته می‌شود»."}},"track":"gt","general":true,"patterns":["GT1-ads"],"often":{"pattern":"GT1-ads","n":24,"of":65,"label":{"en":"Comes up often in the real exam: 24 of the last 65 texts","tr":"Gerçek sınavda sık çıkar: son 65 metnin 24’ünde","fa":"در آزمون واقعی زیاد می‌آید: در ۲۴ متن از ۶۵ متنِ اخیر"}}}]},"points":[{"eyebrow":{"en":"In the exam","tr":"Sınavda","fa":"در آزمون"},"head":{"en":"Seven statements, then seven more","tr":"Yedi ifade, sonra yedi tane daha","fa":"هفت جمله، بعد هفت جمله‌ی دیگر"},"body":{"en":"Questions 1-7: which event, A-E, does each statement describe? Some letters are used more than once. Questions 8-14: TRUE, FALSE or NOT GIVEN about the second text, in the order of the text.","tr":"Soru 1-7: her ifade A-E’den hangi etkinliği anlatıyor? Bazı harfler birden fazla kullanılır. Soru 8-14: ikinci metin hakkında, metnin sırasıyla TRUE, FALSE ya da NOT GIVEN.","fa":"سؤال‌های ۱ تا ۷: هر جمله کدام رویداد، A تا E، را توصیف می‌کند؟ بعضی حرف‌ها بیش از یک بار می‌آیند. سؤال‌های ۸ تا ۱۴: TRUE، FALSE یا NOT GIVEN درباره‌ی متن دوم، به ترتیب متن."}},{"eyebrow":{"en":"The method","tr":"Yöntem","fa":"روش"},"head":{"en":"One idea per statement","tr":"Her ifade için tek fikir","fa":"برای هر جمله یک ایده"},"steps":[{"en":"Reduce each statement to one key idea: adults, weather, make, free, dogs, tickets.","tr":"Her ifadeyi tek bir ana fikre indir: yetişkinler, hava, yapmak, ücretsiz, köpekler, biletler.","fa":"هر جمله را به یک ایده‌ی کلیدی خلاصه کن: بزرگسال، هوا، ساختن، رایگان، سگ، بلیت."},{"en":"Scan all five adverts for that idea, said in other words.","tr":"Beş ilanın hepsinde bu fikri, başka kelimelerle söylenmiş hâliyle tara.","fa":"هر پنج آگهی را برای همین ایده، با کلمه‌های دیگر، مرور کن."},{"en":"For TRUE/FALSE/NOT GIVEN, watch small words: some, all, only, must, may.","tr":"TRUE/FALSE/NOT GIVEN için küçük kelimelere dikkat et: some, all, only, must, may.","fa":"برای TRUE/FALSE/NOT GIVEN حواست به کلمه‌های کوچک باشد: some، all، only، must، may."}]},{"eyebrow":{"en":"The trap","tr":"Tuzak","fa":"دام"},"head":{"en":"Some is not all","tr":"Bazısı hepsi değildir","fa":"بعضی یعنی همه نیست"},"body":{"en":"Information texts are careful with their words. \"Particularly suitable for beginners\" does not mean only beginners can come. \"Some shops\" does not mean every shop. A statement that makes the text stronger than it is will be FALSE.","tr":"Bilgi metinleri kelimelerini dikkatle seçer. \"Özellikle yeni başlayanlar için uygun\", yalnızca yeni başlayanların gelebileceği anlamına gelmez. \"Bazı dükkânlar\" her dükkân demek değildir. Metni olduğundan daha güçlü gösteren bir ifade FALSE olur.","fa":"متن‌های اطلاع‌رسانی کلمه‌هایشان را با دقت انتخاب می‌کنند. «به‌خصوص برای مبتدی‌ها مناسب است» یعنی فقط مبتدی‌ها می‌توانند بیایند نیست. «بعضی مغازه‌ها» یعنی همه‌ی مغازه‌ها نیست. جمله‌ای که متن را قوی‌تر از آنچه هست نشان دهد FALSE است."}}],"example":{"eyebrow":{"en":"Worked example","tr":"Çözümlü örnek","fa":"مثال حل‌شده"},"head":{"en":"One advert, step by step","tr":"Bir ilan, adım adım","fa":"یک آگهی، قدم به قدم"},"instruction":"Which event would suit someone who cannot go out in the evening?","text":"\"A  Quiz Night: Thursday, 7.30 pm.\" · \"B  Book Swap: Saturday, 10 am to 1 pm, in the library.\"","item":"Which event, A or B?","answer":"B","walk":[{"en":"Key idea: not in the evening, so a daytime event.","tr":"Ana fikir: akşam değil, yani gündüz bir etkinlik.","fa":"ایده‌ی کلیدی: نه عصر، پس رویدادی در روز."},{"en":"A starts at 7.30 pm: that is the evening.","tr":"A akşam 7.30’da başlıyor: bu akşam.","fa":"A ساعت ۷:۳۰ عصر شروع می‌شود: یعنی عصر."},{"en":"B runs from 10 am to 1 pm: B.","tr":"B sabah 10’dan öğlen 1’e kadar: B.","fa":"B از ۱۰ صبح تا ۱ بعدازظهر است: B."}]},"quick":{"prompt":"Text: \"The course is especially popular with students.\" Statement: \"Only students can join the course.\" TRUE, FALSE or NOT GIVEN?","options":["NOT GIVEN","TRUE","FALSE"],"correct":0,"why":{"en":"Being popular with students tells you nothing about who is allowed to join.","tr":"Öğrenciler arasında popüler olması, kimin katılabileceği hakkında bir şey söylemez.","fa":"محبوب بودن بین دانشجوها چیزی درباره‌ی اینکه چه کسانی اجازه‌ی ثبت‌نام دارند نمی‌گوید."}},"remember":{"en":"Reduce each statement to one idea, scan every advert for it, and never let \"some\" become \"all\".","tr":"Her ifadeyi tek bir fikre indir, onu her ilanda tara ve \"some\"ın \"all\"a dönüşmesine asla izin verme.","fa":"هر جمله را به یک ایده تبدیل کن، همه‌ی آگهی‌ها را برایش مرور کن و هیچ‌وقت نگذار «some» به «all» تبدیل شود."},"type":"explain","id":"c-x07-r1-e-gt","course":"ielts-exams","exam":"exam-07","unit":"x07-r1"},"drill":{"type":"drill","skill":"reading","part":"General Training Reading Section 1","title":{"en":"Weekend events and a driving course","tr":"Hafta sonu etkinlikleri ve bir sürüş kursu","fa":"رویدادهای آخر هفته و یک دوره‌ی رانندگی"},"timed":20,"ctx":["GT1-ads"],"texts":[{"title":"What’s on this weekend in Kelsall","kind":"adverts","body":"A  Riverside Food and Music Night\nFriday from 6 pm on the riverside walk. Over thirty street-food stalls and live bands until 11 pm. Entry is free, and you pay only for what you eat and drink. Arrive early for a table, as seats near the stage go quickly. Most stalls accept cards, but a few smaller traders take cash only.\n\nB  Kelsall Craft Fair\nSaturday and Sunday, 10 am to 5 pm, at the Town Hall. Browse work by more than fifty local makers, from pottery to jewellery. Join one of our short workshops and go home with a candle or a basket you have made yourself. Adults £2, under-16s free. Workshop places can be booked on the day at the information desk.\n\nC  Films under the Stars\nSaturday at 8.30 pm in Victoria Gardens. This week's open-air screening is a classic family adventure. Bring a blanket or a folding chair; there is no seating. Hot drinks and popcorn are on sale. Please note that the screening will not go ahead if it is raining, so check our website before you set off.\n\nD  Classic Car Show\nSunday, 9 am to 4 pm, in the field behind the cricket club. Around 200 cars from the 1920s to the 1980s, with owners happy to answer questions. At midday there is a parade of the oldest vehicles around the field, followed by a prize for the best-kept car. Parking is £5 per car, payable at the gate. Well-behaved dogs on leads are very welcome, and water bowls are provided.\n\nE  Comedy at the Corn Store\nSaturday at 9 pm. Four of the region's funniest performers in one evening. Some material may not be suitable for younger audiences, so this show is for over-18s only. Tickets must be bought online in advance; none will be sold at the door."},{"title":"Highway Skills: confident motorway driving course","kind":"course information","body":"Many drivers pass their test without ever having driven on a motorway, and some find the experience stressful for years afterwards. Our half-day course is designed to help you feel safe and confident at high speed. It is run by fully qualified instructors who specialise in motorway driving, and every lesson takes place on real roads, not on a simulator.\n\nWho is it for?\nThe course is particularly useful for drivers who have passed their test in the last two years, but it is open to anyone with a full licence. Many of our students are experienced drivers who simply want to refresh their skills.\n\nWhat happens on the course?\nYou will drive one of our dual-control cars, so the instructor can take control if necessary. You will practise joining and leaving the motorway, changing lanes safely, keeping a safe distance and dealing with roadworks. We also explain how variable speed limits work on the newer motorways, and what to do if your car breaks down. The instructor will give you feedback throughout, and a short written summary at the end so that you know what to practise.\n\nCost\nThe course costs £95. Drivers under 25 pay a reduced price of £75. The price includes the use of the car and fuel.\n\nInsurance\nSome insurance companies offer lower premiums to drivers who have completed the course. Contact your insurer before you book to find out whether yours does.\n\nAt the end of the course\nEvery participant receives a certificate, which you can show to your insurer or employer. There is no test at the end, and nobody can fail.\n\nBooking\nCourses run on weekday mornings and Saturdays. Please book at least two weeks in advance. If you need to cancel, let us know at least 48 hours before the start, or the full fee will be charged."}],"groups":[{"text":0,"instruction":"Questions 1-7. Look at the five adverts, A-E. Which event does each statement describe? Write the correct letter, A-E, in boxes 1-7 on your answer sheet. NB You may use any letter more than once.","qtype":"match-info","bank":["A","B","C","D","E"],"questions":[{"n":1,"kind":"match","prompt":"This event is only for adults.","correct":4,"evidence":"this show is for over-18s only","why":{"en":"E: \"this show is for over-18s only\".","tr":"E: \"bu gösteri yalnızca 18 yaş üstü içindir\".","fa":"E: «این برنامه فقط برای بالای ۱۸ سال است»."},"trap":["TR-paraphrase"]},{"n":2,"kind":"match","prompt":"This event may be cancelled because of the weather.","correct":2,"evidence":"the screening will not go ahead if it is raining","why":{"en":"C: \"the screening will not go ahead if it is raining\".","tr":"C: \"yağmur yağarsa gösterim yapılmayacak\".","fa":"C: «اگر باران ببارد، نمایش برگزار نمی‌شود»."},"trap":["TR-paraphrase"]},{"n":3,"kind":"match","prompt":"Visitors can make something to take home.","correct":1,"evidence":"go home with a candle or a basket you have made yourself","why":{"en":"B: workshops where you \"go home with a candle or a basket you have made yourself\".","tr":"B: \"kendi yaptığın bir mum ya da sepetle eve döndüğün\" atölyeler.","fa":"B: کارگاه‌هایی که در آن «با شمع یا سبدی که خودت ساخته‌ای به خانه برمی‌گردی»."},"trap":["TR-paraphrase"]},{"n":4,"kind":"match","prompt":"There is no charge to get in.","correct":0,"evidence":"Entry is free, and you pay only for what you eat and drink","why":{"en":"A: \"Entry is free\". D charges for parking and B charges adults.","tr":"A: \"Giriş ücretsiz\". D otopark için, B yetişkinler için ücret alıyor.","fa":"A: «ورود رایگان است». D برای پارکینگ و B برای بزرگسال‌ها پول می‌گیرد."},"trap":["TR-samewords"]},{"n":5,"kind":"match","prompt":"Visitors are welcome to bring a dog.","correct":3,"evidence":"Well-behaved dogs on leads are very welcome","why":{"en":"D: \"Well-behaved dogs on leads are very welcome\".","tr":"D: \"Tasmalı, uslu köpekler çok hoş karşılanır\".","fa":"D: «سگ‌های آرام با قلاده خیلی خوش‌آمدند»."},"trap":["TR-paraphrase"]},{"n":6,"kind":"match","prompt":"Children can attend without paying.","correct":1,"evidence":"under-16s free","why":{"en":"B: \"Adults £2, under-16s free\". B is used for the second time.","tr":"B: \"Yetişkinler 2 £, 16 yaş altı ücretsiz\". B ikinci kez kullanılıyor.","fa":"B: «بزرگسال‌ها ۲ پوند، زیر ۱۶ سال رایگان». B برای بار دوم استفاده می‌شود."},"trap":["TR-detail"]},{"n":7,"kind":"match","prompt":"Tickets must be bought before the day.","correct":4,"evidence":"Tickets must be bought online in advance","why":{"en":"E: \"Tickets must be bought online in advance; none will be sold at the door.\" B’s workshops are booked on the day.","tr":"E: \"Biletler önceden çevrim içi alınmalı; kapıda satılmayacak.\" B’nin atölyeleri o gün ayırtılıyor.","fa":"E: «بلیت‌ها باید از قبل آنلاین خریده شوند؛ دم در فروخته نمی‌شوند». کارگاه‌های B همان روز رزرو می‌شوند."},"trap":["TR-samewords"]}]},{"text":1,"instruction":"Questions 8-14. Do the following statements agree with the information given in the text? In boxes 8-14 on your answer sheet, write TRUE if the statement agrees with the information, FALSE if the statement contradicts the information, NOT GIVEN if there is no information on this.","qtype":"tfng","questions":[{"n":8,"kind":"tfng","prompt":"The course is only for people who have recently passed their driving test.","correct":"FALSE","evidence":"it is open to anyone with a full licence","why":{"en":"It is \"particularly useful\" for new drivers, but \"open to anyone with a full licence\".","tr":"Yeni sürücüler için \"özellikle yararlı\" ama \"tam ehliyeti olan herkese açık\".","fa":"برای راننده‌های تازه «به‌خصوص مفید است»، اما «برای هر کسی که گواهینامه‌ی کامل دارد باز است»."},"trap":["TR-hedge"]},{"n":9,"kind":"tfng","prompt":"Participants drive their own cars on the course.","correct":"FALSE","evidence":"You will drive one of our dual-control cars","why":{"en":"\"You will drive one of our dual-control cars.\"","tr":"\"Çift kumandalı arabalarımızdan birini kullanacaksın.\"","fa":"«با یکی از ماشین‌های دوفرمانِ ما رانندگی می‌کنی»."},"trap":["TR-NGvsF"]},{"n":10,"kind":"tfng","prompt":"The course includes some driving after dark.","correct":"NOT GIVEN","evidence":"You will practise joining and leaving the motorway","why":{"en":"The list of skills says nothing about driving at night.","tr":"Beceri listesi gece sürüşünden hiç söz etmiyor.","fa":"فهرست مهارت‌ها چیزی درباره‌ی رانندگی در شب نمی‌گوید."},"trap":["TR-NGvsF"]},{"n":11,"kind":"tfng","prompt":"Younger drivers pay less for the course.","correct":"TRUE","evidence":"Drivers under 25 pay a reduced price of £75","why":{"en":"\"Drivers under 25 pay a reduced price.\"","tr":"\"25 yaş altı sürücüler indirimli fiyat öder.\"","fa":"«راننده‌های زیر ۲۵ سال قیمت کمتری می‌دهند»."},"trap":["TR-paraphrase"]},{"n":12,"kind":"tfng","prompt":"Every insurance company offers a discount to drivers who complete the course.","correct":"FALSE","evidence":"Some insurance companies offer lower premiums","why":{"en":"\"Some insurance companies\" is not \"every\" company.","tr":"\"Bazı sigorta şirketleri\", \"her\" şirket değildir.","fa":"«بعضی شرکت‌های بیمه» یعنی «همه‌ی» شرکت‌ها نیست."},"trap":["TR-hedge"]},{"n":13,"kind":"tfng","prompt":"Everyone who completes the course is given a certificate.","correct":"TRUE","evidence":"Every participant receives a certificate","why":{"en":"\"Every participant receives a certificate\"; there is no test.","tr":"\"Her katılımcı bir sertifika alır\"; sınav yok.","fa":"«هر شرکت‌کننده یک گواهی می‌گیرد»؛ امتحانی در کار نیست."},"trap":["TR-paraphrase"]},{"n":14,"kind":"tfng","prompt":"Most people book the course as a present for someone else.","correct":"NOT GIVEN","evidence":"Please book at least two weeks in advance","why":{"en":"The text explains when and how to book, not who books or why.","tr":"Metin ne zaman ve nasıl rezervasyon yapılacağını anlatıyor, kimin ya da neden yaptığını değil.","fa":"متن می‌گوید کی و چطور رزرو کنی، نه اینکه چه کسی و چرا رزرو می‌کند."},"trap":["TR-NGvsF"]}]}],"id":"c-x07-r1-d-gt","course":"ielts-exams","exam":"exam-07","unit":"x07-r1"},"exit":{"type":"exit","items":[{"tests":"word","point":1,"prompt":"\"Tickets must be bought in advance.\" In advance means...","options":["at the door","after the event","before the day of the event"],"correct":2,"why":{"en":"In advance = beforehand.","tr":"In advance = önceden.","fa":"in advance یعنی از قبل."}},{"tests":"paraphrase","point":1,"prompt":"A statement says \"adults only\". Which words in an advert match?","options":["children under 5 free","for over-18s only","family tickets available"],"correct":1,"why":{"en":"Over-18s only = adults only.","tr":"Yalnızca 18 yaş üstü = yalnızca yetişkinler.","fa":"فقط بالای ۱۸ سال یعنی فقط بزرگسالان."}},{"tests":"method","point":2,"prompt":"You have five adverts and seven statements. After matching two statements to B, a third seems to fit B too. What do you do?","options":["Check it carefully; B can be used again","Choose another letter at once","Leave it blank"],"correct":0,"why":{"en":"Letters can be reused; check the meaning, not how often you have used B.","tr":"Harfler yeniden kullanılabilir; B’yi kaç kez kullandığına değil, anlama bak.","fa":"حرف‌ها دوباره قابل استفاده‌اند؛ به معنی نگاه کن، نه به اینکه چند بار B را به کار برده‌ای."}},{"tests":"trap","point":3,"prompt":"Text: \"Some gyms offer a free first session.\" Statement: \"All gyms offer a free first session.\"","options":["TRUE","NOT GIVEN","FALSE"],"correct":2,"why":{"en":"\"Some\" contradicts \"all\".","tr":"\"Some\", \"all\" ile çelişiyor.","fa":"«some» با «all» تناقض دارد."}}],"id":"c-x07-r1-x-gt","course":"ielts-exams","exam":"exam-07","unit":"x07-r1"}}}; })(globalThis.IELTS_EXAMS = globalThis.IELTS_EXAMS || {});
